    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: A child can use a fork, copy a circle, and ride a tricycle. What is the most likely age?', '["2 years", "3 years", "4 years", "5 years"]', 1, 'The "Rule of 3s" includes 3-word sentences, tricycle, and circle. (Nelson)'),
    (v_topic_id, '102: At what age should a child be able to tie their own shoelaces?', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Complex fine motor tasks like tying shoes are typically 5-year-old milestones. (Harriet Lane)'),
    (v_topic_id, '103: A 4-year-old child should be able to do which of the following?', '["Draw a square", "Tie a bow", "Read simple words", "Balance on one foot for 10 seconds"]', 0, 'Drawing a square/cross is a 4-year-old milestone. (Case Files)'),
    (v_topic_id, '104: What is the most common cause of delayed speech in a toddler?', '["Autism", "Hearing loss", "Environmental deprivation", "Mental retardation"]', 1, 'Always rule out hearing loss first with any speech delay. (Nelson)'),
    (v_topic_id, '105: A 2-year-old child presents with a "tantrum" in the grocery store. What is the most appropriate advice for the parents?', '["Spank the child", "Give in to the child''s demands to stop the noise", "Ignore the behavior (time-out or extinction)", "Start the child on Ritalin"]', 2, 'Ignoring the behavior (not providing reinforcement) is the key to managing tantrums. (Harriet Lane)'),
    (v_topic_id, '106: Which of the following is a normal behavior for a 3-year-old child?', '["Parallel play", "Magical thinking", "Sharing toys easily", "Sitting still for 1 hour"]', 1, 'Magical thinking (e.g., believing their thoughts caused an event) is normal in the preschool years. (Case Files)'),
    (v_topic_id, '107: At what age is "stranger anxiety" considered a normal developmental finding?', '["Birth to 3 months", "6 months to 2 years", "3 years to 5 years", "Never"]', 1, 'Stranger anxiety peaks around 9-12 months and resolves by age 2. (Nelson)'),
    (v_topic_id, '108: A child presents with "nocturnal enuresis" (bed-wetting) at age 4. What is the appropriate management?', '["Start Desmopressin", "Punish the child for wet sheets", "Reassure parents that this is normal until age 5", "Refer to urology"]', 2, 'Nocturnal enuresis is not considered pathologic until age 5. (Harriet Lane)'),
    (v_topic_id, '109: What is the first-line non-pharmacologic treatment for nocturnal enuresis in a 7-year-old?', '["Fluid restriction", "Enuresis alarm", "Desmopressin", "Imipramine"]', 1, 'Bed-wetting alarms have the highest long-term cure rate. (Case Files)'),
    (v_topic_id, '110: A child refuses to go to school and develops stomachaches every Monday morning. What is the most likely diagnosis?', '["Appendicitis", "School refusal (School phobia)", "Malingering", "Gastroenteritis"]', 1, 'School refusal is often a form of separation anxiety. (Nelson)'),
    (v_topic_id, '111: What is the primary goal of managing school refusal?', '["Allow the child to stay home until they feel better", "Immediate return to the classroom", "Home schooling", "Starting anti-anxiety meds immediately"]', 1, 'The longer a child stays home, the harder it is to return. (Harriet Lane)'),
    (v_topic_id, '112: Which of the following is the most common cause of mortality in adolescents?', '["Cancer", "Heart disease", "Accidents (unintentional injury)", "Infection"]', 2, 'MVAs, drowning, and other accidents are the #1 cause of death in teens. (Nelson)'),
    (v_topic_id, '113: In an adolescent patient, "confidentiality" should be broken in which of the following scenarios?', '["The patient is sexually active", "The patient is using tobacco", "The patient expresses clear intent to harm themselves or others", "The patient is skipping school"]', 2, 'Safety is the primary reason to breach confidentiality. (Case Files)'),
    (v_topic_id, '114: A 14-year-old female presents for a well-check. She has not yet started her period but has breast development (Tanner 3). What is the appropriate management?', '["Order an MRI of the brain", "Perform a chromosome analysis", "Reassure her that menarche usually follows breast development by 2-2.5 years", "Start estrogen"]', 2, 'The sequence is typically thelarche (breasts) -> pubarche (hair) -> menarche. (Nelson)'),
    (v_topic_id, '115: What is the first sign of puberty in a male?', '["Voice deepening", "Pubic hair growth", "Testicular enlargement", "Facial hair"]', 2, 'Testicular enlargement (volume >4 mL) is the hallmark of Tanner stage 2 in boys. (Harriet Lane)'),
    (v_topic_id, '116: What is the first sign of puberty in a female?', '["Menarche", "Axillary hair", "Breast bud development (thelarche)", "Growth spurt"]', 2, 'Thelarche is typically the first visible sign. (Case Files)'),
    (v_topic_id, '117: Precocious puberty is defined as the onset of secondary sexual characteristics before what age in girls?', '["8 years", "10 years", "12 years", "13 years"]', 0, 'In girls, <8 years is considered precocious. (Nelson)'),
    (v_topic_id, '118: Precocious puberty is defined as the onset of secondary sexual characteristics before what age in boys?', '["9 years", "11 years", "13 years", "14 years"]', 0, 'In boys, <9 years is considered precocious. (Harriet Lane)'),
    (v_topic_id, '119: What is the most common cause of delayed puberty in both boys and girls?', '["Hypothyroidism", "Turners syndrome", "Constitutional delay of growth and puberty", "Pituitary tumor"]', 2, '"Late bloomers" with a positive family history are common. (Case Files)'),
    (v_topic_id, '120: A child has a "bone age" that is equal to their chronological age, but they are short. Diagnosis?', '["Constitutional delay", "Genetic short stature", "Growth hormone deficiency", "Hypothyroidism"]', 1, 'In genetic short stature, bone age matches chronological age. (Nelson)'),
    (v_topic_id, '121: A child has a "bone age" that is significantly younger than their chronological age. Diagnosis?', '["Genetic short stature", "Constitutional delay of growth", "Premature adrenarche", "Precocious puberty"]', 1, 'Delayed bone age suggests potential for "catch-up" growth. (Harriet Lane)'),
    (v_topic_id, '122: What is the most appropriate next step for a 16-year-old female who has never had a period and has NO breast development?', '["Wait until age 18", "Order a pregnancy test", "Perform a pelvic exam", "Evaluate for primary amenorrhea (e.g., FSH, LH, Ultrasound)"]', 3, 'Absence of secondary sexual characteristics by age 13 or menarche by age 15 requires evaluation. (Case Files)'),
    (v_topic_id, '123: Which of the following is a common side effect of stimulant medication for ADHD?', '["Weight gain", "Appetite suppression and insomnia", "Bradycardia", "Somnolence"]', 1, 'Stimulants often cause decreased appetite and trouble falling asleep. (Nelson)'),
    (v_topic_id, '124: What is the recommended screen time for children under 18 months of age (excluding video chatting)?', '["1 hour/day", "2 hours/day", "Zero screen time", "30 minutes/day"]', 2, 'The AAP recommends avoiding digital media (except video chat) for infants <18-24 months. (AAP)'),
    (v_topic_id, '125: At what age should a child be transitioned from a rear-facing to a forward-facing car seat?', '["1 year", "When they reach the maximum weight/height for the rear-facing seat (usually 2+ years)", "4 years", "6 years"]', 1, 'Rear-facing is safest for as long as possible. (AAP Guidelines)'),
    (v_topic_id, '126: A child presents with a "honey-colored" crusting lesion near the nose. What is the most likely diagnosis?', '["Herpes Simplex", "Impetigo", "Eczema", "Psoriasis"]', 1, 'Classic description for impetigo. (Case Files)'),
    (v_topic_id, '127: What is the maintenance fluid rate for a 5-kg infant?', '["20 mL/hr", "40 mL/hr", "50 mL/hr", "100 mL/hr"]', 0, '4 mL/kg/hr for the first 10kg. 4x5 = 20. (Harriet Lane)'),
    (v_topic_id, '128: How many calories does 100 mL of standard breast milk provide?', '["20 kcal", "67 kcal", "100 kcal", "200 kcal"]', 1, 'Breast milk is ~20 kcal/oz, which is ~67 kcal/100 mL. (Nelson)'),
    (v_topic_id, '129: What is the most common cause of neonatal mortality in the US?', '["Congenital anomalies", "Prematurity and low birth weight", "SIDS", "Infection"]', 1, 'Preterm birth complications are the leading cause of neonatal death. (Nelson)'),
    (v_topic_id, '130: Which of the following is the most important factor in preventing pediatric obesity?', '["Low-fat diets", "Sugar-sweetened beverage restriction and increased physical activity", "Multivitamins", "Skipping breakfast"]', 1, 'Behavioral changes and reducing liquid calories are key. (AAP)'),
    (v_topic_id, '131: A child has a BMI at the 90th percentile for their age and gender. They are considered:', '["Normal weight", "Overweight", "Obese", "Severely obese"]', 1, '85th-95th percentile is overweight; >=95th is obese. (CDC)'),
    (v_topic_id, '132: What is the "10-20-30" rule for maintenance fluids in a 24-hour period?', '["100/50/20 mL/kg", "10/20/30 mL/kg", "50/20/10 mL/kg", "None"]', 0, 'Holliday-Segar: 100mL/kg for first 10kg, 50mL/kg for next 10kg, 20mL/kg for remaining weight. (Nelson)'),
    (v_topic_id, '133: A 30-kg child needs maintenance fluids for 24 hours. Total volume?', '["1500 mL", "1700 mL", "2000 mL", "2500 mL"]', 1, '1000 (10x100) + 500 (10x50) + 200 (10x20) = 1700 mL. (Harriet Lane)'),
    (v_topic_id, '134: What is the most appropriate fluid for bolus resuscitation in a child with shock?', '["D5 1/2 Normal Saline", "0.9% Normal Saline (Normal Saline)", "Sterile water", "5% Albumin"]', 1, 'Isotonic crystalloids like NS or LR are the standard. (PALS)'),
    (v_topic_id, '135: A child has a serum sodium of 120 mEq/L. What is the risk of correcting this too rapidly?', '["Cerebral edema", "Central Pontine Myelinolysis (Osmotic Demyelination Syndrome)", "Seizures", "Heart failure"]', 1, 'Rapid correction of chronic hyponatremia causes demyelination. (Nelson)'),
    (v_topic_id, '136: A child has a serum sodium of 170 mEq/L (Hypernatremia). What is the risk of correcting this too rapidly?', '["Cerebral edema", "Demyelination", "Dehydration", "Fever"]', 0, 'Rapid drops in osmolarity cause water to rush into brain cells. (Harriet Lane)'),
    (v_topic_id, '137: What is the recommended maximum rate of sodium correction in chronic hypernatremia?', '["2 mEq/L/hr", "0.5 mEq/L/hr (or <10-12 mEq/L per day)", "5 mEq/L/hr", "10 mEq/L/hr"]', 1, 'Slow correction prevents cerebral edema. (Case Files)'),
    (v_topic_id, '138: A child presents with "tetany" and a positive Chvostek sign (facial twitching). What electrolyte is likely low?', '["Sodium", "Potassium", "Calcium", "Magnesium"]', 2, 'Hypocalcemia causes neuromuscular irritability. (Nelson)'),
    (v_topic_id, '139: Which ECG finding is classic for hyperkalemia?', '["U waves", "Peaked T waves", "Shortened PR interval", "ST elevation"]', 1, 'Peaked T waves are the earliest sign of potassium toxicity. (Harriet Lane)'),
    (v_topic_id, '140: What is the immediate treatment for severe hyperkalemia with ECG changes?', '["IV Insulin and Glucose", "IV Calcium Gluconate (to stabilize membranes)", "Sodium Polystyrene Sulfonate (Kayexalate)", "Furosemide"]', 1, 'Calcium does not lower K+ but protects the heart from arrhythmias. (Case Files)'),
    (v_topic_id, '141: At what age should a child transition from a crib to a bed?', '["12 months", "When they can climb out of the crib or reach 35 inches tall", "3 years", "5 years"]', 1, 'Safety is the primary driver for the transition. (AAP)'),
    (v_topic_id, '142: Which of the following is a symptom of "nightmares" but NOT "night terrors"?', '["Occurs in first half of night", "Child is inconsolable during the event", "Child remembers the dream and can be comforted", "No memory of the event"]', 2, 'Nightmares occur in REM sleep (late night); child is awake and alert after. (Nelson)'),
    (v_topic_id, '143: A child is "marking time" while going up stairs (putting both feet on each step). What age?', '["18 months", "2 years", "3 years", "4 years"]', 1, 'Marking time is 2y; alternating feet is 3y. (Harriet Lane)'),
    (v_topic_id, '144: A child can walk down stairs alternating feet. Age?', '["3 years", "4 years", "5 years", "6 years"]', 1, 'Walking down alternating is a 4-year-old skill. (Case Files)'),
    (v_topic_id, '145: At what age is "autism-specific" screening (e.g., M-CHAT) recommended?', '["6 and 12 months", "18 and 24 months", "3 and 5 years", "Every visit"]', 1, 'Formal screening is done at 18 and 24 months. (AAP)'),
    (v_topic_id, '146: What is the "Head circumference-for-age" percentile that defines microcephaly?', '["< 10th percentile", "< 5th percentile", "< 2nd percentile (or 2SD below mean)", "< 50th percentile"]', 2, 'Significant deviation below the mean is microcephaly. (Nelson)'),
    (v_topic_id, '147: Macrocephaly is defined as head circumference > what percentile?', '["90th", "95th", "98th (or 2SD above mean)", "75th"]', 2, 'May be benign (familial) or pathologic (hydrocephalus). (Harriet Lane)'),
    (v_topic_id, '148: A child has "growing pains" that occur at night and wake the child up. They are bilateral and gone by morning. Management?', '["Bone scan", "Reassurance and massage/heat", "Aspirin", "Refer to oncology"]', 1, 'Growing pains are common and never associated with daytime limping or systemic symptoms. (Case Files)'),
    (v_topic_id, '149: Which of the following is a "red flag" in a child with a limp?', '["Pain only at night", "Systemic symptoms (fever, weight loss) and refusal to bear weight", "Pain that resolves with activity", "History of minor trauma"]', 1, 'Refusal to bear weight is a major concern for infection or malignancy. (Nelson)'),
    (v_topic_id, '150: What is the most common cause of painless scrotal swelling in a toddler?', '["Testicular torsion", "Hydrocele", "Inguinal hernia", "Varicocele"]', 1, 'Communicating hydroceles are common in young children. (Harriet Lane)'),
    (v_topic_id, '151: A child has a "bag of worms" feel in the scrotum. Diagnosis?', '["Hydrocele", "Spermatocele", "Varicocele", "Epididymitis"]', 2, 'Varicoceles are more common in older adolescents. (Case Files)'),
    (v_topic_id, '152: Testicular torsion is a surgical emergency. What is the "golden window" for salvage?', '["2 hours", "6 hours", "12 hours", "24 hours"]', 1, 'Detorsion within 6 hours has the best outcome for the testis. (Nelson)'),
    (v_topic_id, '153: A child has "amenorrhea" and a high FSH. Diagnosis?', '["Hypothalamic amenorrhea", "Turner Syndrome (Ovarian failure)", "Pregnancy", "PCOS"]', 1, 'High FSH indicates the brain is trying to stimulate non-functional ovaries. (Harriet Lane)'),
    (v_topic_id, '154: What is the most common chromosomal abnormality in humans?', '["Trisomy 21 (Down Syndrome)", "Turner Syndrome", "Klinefelter Syndrome", "Trisomy 18"]', 0, 'Down Syndrome is the leading genetic cause of intellectual disability. (Nelson)'),
    (v_topic_id, '155: A child has up-slanting palpebral fissures, a single transverse palmar crease, and hypotonia. Diagnosis?', '["Trisomy 13", "Trisomy 21", "Fragile X", "Noonan syndrome"]', 1, 'Classic features of Down Syndrome. (Case Files)'),
    (v_topic_id, '156: What is the most common congenital heart defect associated with Down Syndrome?', '["VSD", "Atrioventricular Septal Defect (Endocardial cushion defect)", "PDA", "ToF"]', 1, 'AVSD is highly associated with Trisomy 21. (Nelson)'),
    (v_topic_id, '157: A child with Down Syndrome is at increased risk for which gastrointestinal condition?', '["Intussusception", "Duodenal atresia (''double bubble'' sign)", "Appendicitis", "GERD"]', 1, 'Duodenal atresia is a classic association. (Harriet Lane)'),
    (v_topic_id, '158: Which of the following is an increased risk for children with Down Syndrome as they age?', '["Acute Leukemia", "Early-onset Alzheimer''s", "Hypothyroidism", "All of the above"]', 3, 'These patients require lifelong monitoring for multiple comorbidities. (Case Files)'),
    (v_topic_id, '159: What is the most common cause of inherited intellectual disability in males?', '["Down Syndrome", "Fragile X Syndrome", "Prader-Willi", "Klinefelter"]', 1, 'Fragile X is caused by a CGG repeat expansion. (Nelson)'),
    (v_topic_id, '160: A male has large ears, a long face, and macroorchidism (large testes). Diagnosis?', '["Klinefelter", "Fragile X", "Marfan", "Homocystinuria"]', 1, 'Classic phenotype for Fragile X. (Harriet Lane)'),
    (v_topic_id, '161: A child has a "cat-like" cry. Diagnosis?', '["Cri-du-chat syndrome (5p deletion)", "Down syndrome", "Edwards syndrome", "Patau syndrome"]', 0, 'Named after the characteristic high-pitched cry. (Nelson)'),
    (v_topic_id, '162: What is the most common symptom of a child with lead poisoning?', '["Abdominal pain", "Encephalopathy", "Asymptomatic (until levels are very high)", "Anemia"]', 2, 'Lead poisoning is usually silent; screening is vital. (Case Files)'),
    (v_topic_id, '163: At what lead level is "chelation therapy" usually considered?', '["5 mcg/dL", "15 mcg/dL", "45 mcg/dL", "70 mcg/dL"]', 2, 'Lower levels require environmental cleanup; >=45 requires medical treatment. (CDC)'),
    (v_topic_id, '164: A child has an "allergic shiners" and a "transverse nasal crease." Diagnosis?', '["Common cold", "Allergic Rhinitis", "Sinusitis", "Foreign body"]', 1, 'The nasal crease comes from the "allergic salute" (rubbing nose up). (Nelson)'),
    (v_topic_id, '165: What is the most common food allergy in children?', '["Peanuts", "Cow''s milk", "Egg", "Soy"]', 1, 'Milk allergy is very common in infants but often outgrown. (Harriet Lane)'),
    (v_topic_id, '166: A child presents with an "anaphylactic" reaction to a bee sting. What is the immediate treatment?', '["IV Diphenhydramine", "IM Epinephrine", "Inhaled Albuterol", "Oral Steroids"]', 1, 'Epinephrine is the only life-saving medication for anaphylaxis. (PALS)'),
    (v_topic_id, '167: Where should an EpiPen be administered?', '["Intravenously", "Intramuscularly into the lateral thigh", "Into the arm", "Into the buttock"]', 1, 'The vastus lateralis is the preferred site for rapid absorption. (Case Files)'),
    (v_topic_id, '168: What is the most common chronic disease of childhood?', '["Diabetes", "Asthma", "Cystic fibrosis", "Arthritis"]', 1, 'Asthma affects millions of children. (Nelson)'),
    (v_topic_id, '169: A child has "atopic dermatitis" (eczema). Where is it typically located in an infant?', '["Extensor surfaces and cheeks", "Flexor surfaces (antecubital fossa)", "Groin", "Scalp only"]', 0, 'Infants get it on the outside of joints; older kids get it in the creases. (Harriet Lane)'),
    (v_topic_id, '170: What is the "atopic triad"?', '["Fever, Rash, Joint pain", "Asthma, Allergic Rhinitis, Atopic Dermatitis", "Cough, Coryza, Conjunctivitis", "None"]', 1, 'These conditions frequently coexist in the same patient. (Case Files)'),
    (v_topic_id, '171: A 12-month-old child can say "Mama" and "Dada" specifically. Is this normal?', '["Yes", "No, they should say 10 words", "No, they should only coo", "No, they should speak in sentences"]', 0, '12 months = 1-3 specific words. (Nelson)'),
    (v_topic_id, '172: At what age should a child have a vocabulary of at least 200 words?', '["18 months", "2 years", "3 years", "4 years"]', 1, 'Two-year-olds have a major vocabulary explosion. (Harriet Lane)'),
    (v_topic_id, '173: A child can use a cup independently. Age?', '["6 months", "12 months", "18 months", "24 months"]', 1, 'Mastered by 1 year. (Case Files)'),
    (v_topic_id, '174: A child can undress themselves. Age?', '["18 months", "2 years", "3 years", "4 years"]', 1, 'Undressing is easier than dressing (2y vs 3-4y). (Nelson)'),
    (v_topic_id, '175: A child can name 1 color and 1 body part. Age?', '["18 months", "2 years", "3 years", "4 years"]', 1, 'Basic naming starts at 18-24 months. (Harriet Lane)'),
    (v_topic_id, '176: A child can balance on one foot for 5 seconds. Age?', '["3 years", "4 years", "5 years", "6 years"]', 1, '4 years = 5 seconds; 5 years = 10 seconds. (Case Files)'),
    (v_topic_id, '177: A child can count 4 objects. Age?', '["3 years", "4 years", "5 years", "6 years"]', 1, 'Counting 4 objects is a 4-year-old skill. (Nelson)'),
    (v_topic_id, '178: A child can name all primary colors. Age?', '["3 years", "4 years", "5 years", "6 years"]', 2, 'Mastery of colors is a 5-year-old milestone. (Harriet Lane)'),
    (v_topic_id, '179: At what age does the "extrusion reflex" (pushing food out of the mouth) typically disappear?', '["2 months", "4-6 months", "9 months", "1 year"]', 1, 'Disappearance of this reflex signals readiness for solids. (Case Files)'),
    (v_topic_id, '180: A child has "pica" (eating non-food items). What deficiency is this associated with?', '["Vitamin D", "Iron", "Vitamin C", "Calcium"]', 1, 'Pica (especially ice or dirt) is a classic sign of iron deficiency. (Nelson)'),
    (v_topic_id, '181: What is the maintenance fluid rate for a 45-kg adolescent?', '["45 mL/hr", "65 mL/hr", "85 mL/hr", "100 mL/hr"]', 2, '40 (first 10) + 20 (next 10) + 25 (remaining 25). Total = 85 mL/hr. (Harriet Lane)'),
    (v_topic_id, '182: A child weighs 22 kg. What is their 24-hour maintenance fluid volume?', '["1000 mL", "1540 mL", "2000 mL", "2200 mL"]', 1, '1000 + 500 + 40 (2x20). Total = 1540 mL. (Case Files)'),
    (v_topic_id, '183: What is the most common electrolyte abnormality in a child with prolonged vomiting?', '["Hypernatremia", "Hyponatremic, hypochloremic metabolic alkalosis", "Hyperkalemia", "Acidosis"]', 1, 'Loss of H+ and Cl- leads to alkalosis. (Nelson)'),
    (v_topic_id, '184: What is the most common cause of metabolic acidosis in a child with severe diarrhea?', '["Loss of gastric acid", "Loss of bicarbonate in stool", "Renal failure", "Toxins"]', 1, 'Diarrhea is "acidosis from below." (Harriet Lane)'),
    (v_topic_id, '185: A child has a serum potassium of 2.5 mEq/L (Hypokalemia). What ECG finding is expected?', '["Peaked T waves", "U waves and flattened T waves", "Wide QRS", "Short QT"]', 1, 'U waves appear as K+ levels drop. (Case Files)'),
    (v_topic_id, '186: Which of the following is the most common cause of hypomagnesemia in a child?', '["Inadequate intake", "Malabsorption or chronic diarrhea", "Excessive sweating", "Diuretics"]', 1, 'GI losses are a major cause. (Nelson)'),
    (v_topic_id, '187: A child has "rickets" (bowing of legs, wrist widening). What is the most common cause?', '["Vitamin C deficiency", "Vitamin D deficiency", "Calcium excess", "Lead poisoning"]', 1, 'Vitamin D is needed for bone mineralization. (Harriet Lane)'),
    (v_topic_id, '188: A child has "scurvy" (bleeding gums, petechiae). Deficiency?', '["Vitamin A", "Vitamin B12", "Vitamin C", "Vitamin K"]', 2, 'Scurvy is rare but occurs with extreme dietary restriction. (Case Files)'),
    (v_topic_id, '189: A child has "xerophthalmia" (dry eyes) and night blindness. Deficiency?', '["Vitamin A", "Vitamin E", "Vitamin D", "Zinc"]', 0, 'Vitamin A is critical for retinal function. (Nelson)'),
    (v_topic_id, '190: What is the treatment for "nursemaid''s knee" (Actually nursemaid''s elbow)?', '["Surgery", "Reduction via supination of forearm and flexion of elbow", "Cast for 6 weeks", "Aspirin"]', 1, 'Subluxation of the radial head is easily reduced in the office. (Harriet Lane)'),
    (v_topic_id, '191: At what age should a child be able to stack a tower of 9 cubes?', '["2 years", "3 years", "4 years", "5 years"]', 1, '3 years = 9 cubes. (Case Files)'),
    (v_topic_id, '192: A child can copy a circle. Age?', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Circle = 3 years. (Nelson)'),
    (v_topic_id, '193: A child can copy a cross. Age?', '["3 years", "4 years", "5 years", "6 years"]', 1, 'Cross = 4 years. (Harriet Lane)'),
    (v_topic_id, '194: A child can copy a square. Age?', '["3 years", "4 years", "5 years", "6 years"]', 1, 'Square = 4 years (sometimes 4.5). (Case Files)'),
    (v_topic_id, '195: A child can copy a triangle. Age?', '["4 years", "5 years", "6 years", "7 years"]', 1, 'Triangle = 5 years. (Nelson)'),
    (v_topic_id, '196: A child can copy a diamond. Age?', '["5 years", "6 years", "7 years", "8 years"]', 1, 'Diamond = 6 years. (Harriet Lane)'),
    (v_topic_id, '197: A 2-year-old is at the 75th percentile for weight and 25th for height. Interpretation?', '["Normal", "Increasing risk of being overweight", "Failure to thrive", "SGA"]', 1, 'Weight for height is increasing. (Case Files)'),
    (v_topic_id, '198: At what age does a child reach 50% of their adult height?', '["1 year", "2 years", "3 years", "5 years"]', 1, 'A child''s 2-year-old height is roughly half their adult height. (Nelson)'),
    (v_topic_id, '199: A child is "marking time" while going DOWN stairs. Age?', '["2 years", "3 years", "4 years", "5 years"]', 1, 'Going up alternating is 3y; going down alternating is 4y. (Harriet Lane)'),
    (v_topic_id, '200: Final Pearl: When is a "breath-holding spell" dangerous?', '["Always", "Never (they are benign, though scary)", "Only if they last 1 minute", "If they happen daily"]', 1, 'They are emotionally triggered and do not cause brain damage. (MediHelp Mastery)');
